"""Low-level tools for creating clients.

This module adds abstractions on top of underlying network protocols and expose
interface that operates on :class:`IStream` objects.
"""

import typing

from jsilib import _utils
from jsilib.base import IClosable

from ._endpoint import load_from_url
from ._tcp import TCPClient
from ._ws import WSClient
from .interface import IReactor, IStream

__all__ = export = _utils.ExportList()


@export
class Client(IClosable):
    """Factory class for the client-side connections.

    :param reactor:
        Reactor to be used by this client.

        All connections created by this client's :meth:`connect` method will
        also use that given reactor object internally.
    """
    _handlers_supported = {
        'tcp': TCPClient,
        'tcp+ssl': TCPClient,
        'ws': WSClient,
        'wss': WSClient,
    }

    def __init__(self, reactor: IReactor):
        self._reactor = reactor
        self._closed = False
        self._handlers_created: typing.List[IClosable] = []

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            for handler in self._handlers_created:
                await handler.close()

    async def connect(self, url: str) -> IStream:
        """Connect with the server at given *url*.

        On success, this function returns an instance of :class:`IStream` class to
        exchange binary data with the server. On failure, :exc:`ConnectFailedError`
        exception is raised.

        :param url:
            The URL address specifying host, port and protocol to be used.

            For example, to connect using TCP with a server at **localhost**,
            listening to at port **8888** you would write:

                tcp://localhost:8888

            Currently supported protocols (i.e. URL schemes) are:

                * tcp - for TCP connections
                * tcp+ssl - for secure TCP connections
                * ws - for WebSocket connections
                * wss - for secure WebSocket connections
        """
        endpoint = load_from_url(url)
        handler_factory = self._handlers_supported.get(endpoint.scheme)
        if handler_factory is None:
            raise ValueError(f'unsupported scheme: {endpoint.scheme}')
        handler = handler_factory(self._reactor)
        self._handlers_created.append(handler)
        return await handler.connect(endpoint)
